// Prints the tool flow of the Anthropic request that follows /tree navigation, for Pi 1.1.0. nav-wire-pig/main.go prints the same for PiG: both build the tree below, navigate to every entry with and without a branch summary through the session's own navigateTree (agent-session.js: the new leaf, the branch summary generated by the model, the summary entry), send a prompt through the session, and print the number of requests the server received, the roles, texts and tool call/result ids of the prompt's request body, and whether the Anthropic tool_result contract holds.
import { PI_PACKAGE_VERSION } from "./pi-version.mjs";
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { createServer } from 'node:http';
import { tmpdir } from 'node:os';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = resolve('extensions/sdk-ts/node_modules/@earendil-works/pi-coding-agent');
assert.equal(JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version, PI_PACKAGE_VERSION);
const load = (rel) => import(pathToFileURL(join(root, 'dist', rel)).href);
const ai = await import(pathToFileURL(join(root, 'node_modules/@earendil-works/pi-ai/dist/compat.js')).href);
const { createAgentSession } = await load('core/sdk.js');
const { ModelRuntime } = await load('core/model-runtime.js');
const { AuthStorage } = await load('core/auth-storage.js');
const { SessionManager } = await load('core/session-manager.js');
const { SettingsManager } = await load('core/settings-manager.js');
const { DefaultResourceLoader } = await load('core/resource-loader.js');

const sse = [
	['message_start', { type: 'message_start', message: { id: 'msg_1', type: 'message', role: 'assistant', model: 'claude-sonnet-4-5', content: [], usage: { input_tokens: 1, output_tokens: 1 } } }],
	['content_block_start', { type: 'content_block_start', index: 0, content_block: { type: 'text', text: '' } }],
	['content_block_delta', { type: 'content_block_delta', index: 0, delta: { type: 'text_delta', text: 'abandoned branch summary' } }],
	['content_block_stop', { type: 'content_block_stop', index: 0 }],
	['message_delta', { type: 'message_delta', delta: { stop_reason: 'end_turn' }, usage: { output_tokens: 1 } }],
	['message_stop', { type: 'message_stop' }],
].map(([name, data]) => `event: ${name}\ndata: ${JSON.stringify(data)}\n\n`).join('');

let lastBody = '';
let requests = 0;
const server = createServer((request, response) => {
	const chunks = [];
	request.on('data', (chunk) => chunks.push(chunk));
	request.on('end', () => {
		lastBody = Buffer.concat(chunks).toString('utf8');
		requests++;
		response.writeHead(200, { 'Content-Type': 'text/event-stream' });
		response.end(sse);
	});
});
await new Promise((done) => server.listen(0, '127.0.0.1', done));
const baseUrl = `http://127.0.0.1:${server.address().port}`;

const usage = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } };
let clock = 1_700_000_000_000;
const user = (text) => ({ role: 'user', content: [{ type: 'text', text }], timestamp: clock++ });
const text = (value) => ({ role: 'assistant', content: [{ type: 'text', text: value }], api: 'openai-responses', provider: 'other', model: 'other-1', usage, stopReason: 'stop', timestamp: clock++ });
const calls = (stopReason, ...ids) => ({ role: 'assistant', content: ids.map((id) => ({ type: 'toolCall', id, name: 'read', arguments: { path: id } })), api: 'openai-responses', provider: 'other', model: 'other-1', usage, stopReason, timestamp: clock++ });
const result = (id) => ({ role: 'toolResult', toolCallId: id, toolName: 'read', content: [{ type: 'text', text: `result ${id}` }], isError: false, timestamp: clock++ });

// The forked tree of coding/session_tree_wire_oracle_test.go: parallel calls, single calls, a branch from between parallel results, a branch at the call message.
function buildTree(sm) {
	const ids = [];
	const add = (message) => { const id = sm.appendMessage(message); ids.push(id); return id; };
	add(user('start'));
	const a1 = add(calls('toolUse', 'c1', 'c2', 'c3'));
	const r1 = add(result('c1'));
	add(result('c2'));
	add(result('c3'));
	add(text('done reading'));
	add(user('next'));
	add(calls('toolUse', 'd1'));
	add(result('d1'));
	add(text('done again'));

	sm.branch(r1);
	add(user('retry after c1'));
	add(calls('toolUse', 'e1', 'e2'));
	add(result('e1'));
	add(result('e2'));
	add(text('done retry'));

	sm.branch(a1);
	add(user('other idea'));
	add(text('other answer'));
	// An errored turn whose result was persisted is left out: Pi sends that orphan tool_result (HTTP 400) and PiG drops it (D48), so the pair differs by design there.
	return { sm, ids };
}

// resultText joins the text of a tool_result's content, a string or text blocks.
function resultText(content) {
	if (typeof content === 'string') return content;
	return (content ?? []).map((block) => (block.type === 'text' ? block.text : `[${block.type}]`)).join('');
}

// flow renders the request's messages as "role[kind:id,text=\"...\",...]" and checks the Anthropic rule: the tool_result blocks of a user message answer exactly the tool_use blocks of the assistant message right before it.
function flow(body) {
	let request;
	try { request = JSON.parse(body); } catch (error) { return ['unparsable', `INVALID: ${error.message}`]; }
	const out = [];
	let open = new Set();
	let problem = '';
	request.messages.forEach((message, i) => {
		const blocks = Array.isArray(message.content) ? message.content : [{ type: 'text', text: message.content }];
		const parts = [];
		const uses = new Set();
		const results = new Set();
		for (const block of blocks) {
			if (block.type === 'tool_use') { uses.add(block.id); parts.push(`tool_use:${block.id}`); }
			else if (block.type === 'tool_result') { results.add(block.tool_use_id); parts.push(`tool_result:${block.tool_use_id}${block.is_error ? ':error' : ''}=${JSON.stringify(resultText(block.content))}`); }
			else if (block.type === 'text') parts.push(`text=${JSON.stringify(block.text)}`);
			else parts.push(String(block.type));
		}
		for (const id of results) {
			if (!open.has(id) && !problem) problem = `INVALID: message ${i} answers "${id}", which the message before it did not call`;
		}
		for (const id of open) {
			if ((message.role === 'assistant' || !results.has(id)) && !problem) problem = `INVALID: message ${i} follows a call to "${id}" that no tool_result answers`;
		}
		open = uses.size > 0 ? uses : new Set();
		out.push(`${message.role}[${parts.join(',')}]`);
	});
	if (open.size > 0 && !problem) problem = 'INVALID: the request ends on an unanswered tool call';
	return [out.join(' '), problem || 'valid'];
}

const model = { ...ai.getModel('anthropic', 'claude-sonnet-4-5'), baseUrl };
const dir = mkdtempSync(join(tmpdir(), 'nav-wire-pi-'));
const settingsManager = SettingsManager.inMemory();
const modelRuntime = await ModelRuntime.create({ credentials: AuthStorage.inMemory({ anthropic: { type: 'api_key', key: 'test-key' } }), modelsPath: null });
const resourceLoader = new DefaultResourceLoader({ cwd: dir, agentDir: dir, settingsManager, noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true });
await resourceLoader.reload();
const openSession = async (sessionManager) => (await createAgentSession({ cwd: dir, agentDir: dir, model, modelRuntime, settingsManager, sessionManager, resourceLoader, noTools: 'all' })).session;
const entries = buildTree(SessionManager.inMemory(dir)).ids.length;
const lines = [];
try {
	for (let index = 0; index < entries; index++) {
		for (const summarize of [false, true]) {
			// As in nav-wire-pig, a new session records its model and thinking level before the tree is appended. Pi's agent reads the session manager when a session opens, so the session that navigates opens after the tree is appended.
			const sm = SessionManager.inMemory(dir);
			(await openSession(sm)).dispose();
			const { ids } = buildTree(sm);
			const session = await openSession(sm);
			const before = requests;
			try {
				await session.navigateTree(ids[index], { summarize });
				await session.prompt('next prompt');
			} finally {
				session.dispose();
			}
			const [shape, verdict] = flow(lastBody);
			lines.push(`entry ${String(index).padStart(2, '0')} summary=${summarize} requests=${requests - before}: ${shape} => ${verdict}`);
		}
	}
} finally {
	rmSync(dir, { recursive: true, force: true });
	server.close();
}
console.log(lines.join('\n'));
